// <auto-generated />

export type FieldError = { field: string; code: string; message: string };

export enum Method {
    Get = 'GET',
    Post = 'POST',
    Put = 'PUT',
    Patch = 'PATCH',
    Delete = 'DELETE',
}

export enum ActionErrorKind {
    Validation = 'validation',
    Http = 'http',
    Network = 'network',
}

export type ActionError =
    | { kind: ActionErrorKind.Validation; errors: FieldError[] }
    | { kind: ActionErrorKind.Http; status: number }
    | { kind: ActionErrorKind.Network };

export type ActionState<T> = {
    data: T | null;
    loading: boolean;
    isError: boolean;
    error: ActionError | null;
};

export const setParam = (
    query: URLSearchParams,
    key: string,
    value: unknown,
): void => {
    if (value !== undefined) query.set(key, String(value));
};
